/**
 * ArvoSidePanel -- content-area-scoped pane that docks at the layout level
 * (default) or overlays sibling content via slide-in animation.
 *
 * Composes the `panel-shell` shared pattern for its inner anatomy (header,
 * sticky region, body, footer, items+filter pipeline, empty/skeleton states)
 * and adds SidePanel-only positional concerns: layout vs in-content overlay
 * mounting, the pin button, the side-aware splitter slot, and the
 * layout/overlay variant flip.
 *
 * See `descriptors/side-panel.json` and `descriptors/side-panel-prompt.md`
 * for the full spec.
 */

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react';
import type { CSSProperties, ReactElement, ReactNode, Ref, RefObject } from 'react';

import { enter, exit, type ListItemBase } from '@arvo/core';
import {
  PanelShell,
  type PanelShellHandle,
} from '../PanelShell/PanelShell';
import ArvoIconButton from '../IconButton/IconButton';
import { useControllableState } from '../../hooks/useControllableState';
import { useFocusTrap } from '../../hooks/useFocusTrap';
import type {
  ArvoPanelHeaderAction,
  ArvoPanelStickyHeaderConfig,
  ArvoPanelBannerConfig,
  ArvoPanelInfoConfig,
  ArvoPanelAction,
} from '@arvo/utils';

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export type ArvoSidePanelVariant = 'layout' | 'overlay';
export type ArvoSidePanelSide = 'left' | 'right';

export interface ArvoSidePanelHandle<T extends ListItemBase = ListItemBase> {
  pinned(value?: boolean): boolean | void;
  setVariant(variant: ArvoSidePanelVariant): void;
  open(): void;
  close(): void;
  toggle(): void;
  isOpen(): boolean;
  setItems(items: T[]): void;
  setStickyHeader(config: ArvoPanelStickyHeaderConfig | false): void;
  setHeaderActions(actions: ArvoPanelHeaderAction[]): void;
  setActions(actions: ArvoPanelAction[] | false): void;
  updateAction(
    id: string,
    patch: Partial<ArvoPanelHeaderAction | ArvoPanelAction>,
  ): void;
  search(query?: string): string | void;
  selectedTab(id?: string): string | null | void;
  setTitle(title: string | null): void;
  loading(state?: boolean): boolean | void;
  disabled(state?: boolean): boolean | void;
  focus(target?: 'first' | 'title' | 'search' | 'list'): void;
}

export interface ArvoSidePanelProps<T extends ListItemBase = ListItemBase>
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onClose' | 'onSelect' | 'title'> {
  variant?: ArvoSidePanelVariant;
  side?: ArvoSidePanelSide;

  isPinnable?: boolean;
  isPinned?: boolean;
  defaultPinned?: boolean;
  onPinChange?: (pinned: boolean) => void;

  hasSplitter?: boolean | 'auto';

  width?: string | number;
  minWidth?: string | number;
  maxWidth?: string | number | null;

  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  onOpen?: () => boolean | void;
  onClose?: () => boolean | void;

  closeOnEscape?: boolean;
  closeOnOutside?: boolean;

  isDisabled?: boolean;
  isLoading?: boolean;

  ariaLabel?: string;
  className?: string;
  children?: ReactNode;

  /**
   * Forwarded to the imperative handle. The forwarded `ref` always points to
   * the host `.arvo-sp` element; use `instanceRef` for the imperative API.
   */
  instanceRef?: Ref<ArvoSidePanelHandle>;

  // -- Forwarded to PanelShell ----------------------------------------------
  title?: string | null;
  hasHeader?: boolean;
  hasBackButton?: boolean;
  onBack?: () => void;
  headerActions?: ArvoPanelHeaderAction[];
  stickyHeader?: ArvoPanelStickyHeaderConfig | false;

  items?: T[];
  getItemId?: (item: T) => string;
  filterKeys?: Array<keyof T & string>;
  getItemSearchText?: (item: T) => string;
  renderItem?: (item: T) => ReactNode;
  itemsRole?: 'listbox' | 'list' | 'menu';

  actions?: ArvoPanelAction[] | false;
  hasFooter?: boolean;
  isClosable?: boolean;

  searchQuery?: string;
  defaultSearchQuery?: string;
  onSearchChange?: (query: string, matchedCount: number | null) => void;
  onItemActivate?: (id: string, item: T) => void;
  onTabSelect?: (id: string) => void;
}

// ---------------------------------------------------------------------------
// Re-exports of panel-shell types (consumer convenience)
// ---------------------------------------------------------------------------

export type {
  ArvoPanelHeaderAction,
  ArvoPanelStickyHeaderConfig,
  ArvoPanelBannerConfig,
  ArvoPanelInfoConfig,
  ArvoPanelAction,
};

// Backwards-compat aliases (descriptor.customTypes).
export type ArvoSidePanelHeaderAction = ArvoPanelHeaderAction;
export type ArvoSidePanelStickyHeaderConfig = ArvoPanelStickyHeaderConfig;
export type ArvoSidePanelBannerConfig = ArvoPanelBannerConfig;
export type ArvoSidePanelInfoConfig = ArvoPanelInfoConfig;
export type ArvoSidePanelAction = ArvoPanelAction;

// ---------------------------------------------------------------------------
// Pin button subcomponent
// ---------------------------------------------------------------------------

interface PinButtonProps {
  isPinned: boolean;
  isDisabled?: boolean;
  onClick: () => void;
}

const PinButton = forwardRef<HTMLButtonElement, PinButtonProps>(function PinButton(
  { isPinned, isDisabled, onClick },
  ref,
) {
  const label = isPinned ? 'Unpin panel' : 'Pin panel';
  return (
    <ArvoIconButton
      ref={ref}
      className="arvo-sp__pin"
      size="sm"
      variant="tertiary"
      icon="push-pin"
      tooltip={label}
      isDisabled={isDisabled}
      isSelected={isPinned}
      onClick={onClick}
      aria-label={label}
    />
  );
});

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function toCssLength(value: string | number | null | undefined): string | undefined {
  if (value === null || value === undefined) return undefined;
  return typeof value === 'number' ? `${value}px` : value;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

function SidePanelInner<T extends ListItemBase = ListItemBase>(
  props: ArvoSidePanelProps<T>,
  ref: React.ForwardedRef<HTMLDivElement>,
) {
  const {
    variant: variantProp = 'layout',
    side = 'right',
    isPinnable = false,
    isPinned: isPinnedProp,
    defaultPinned = true,
    onPinChange,
    hasSplitter = false,
    width = 290,
    minWidth = 280,
    maxWidth = null,
    isOpen: isOpenProp,
    defaultOpen = true,
    onOpenChange,
    onOpen,
    onClose,
    closeOnEscape = true,
    closeOnOutside = false,
    isDisabled = false,
    isLoading = false,
    ariaLabel,
    className,
    children,
    instanceRef,

    // PanelShell passthrough
    title = null,
    hasHeader = true,
    hasBackButton = false,
    onBack,
    headerActions,
    stickyHeader = false,
    items,
    getItemId,
    filterKeys,
    getItemSearchText,
    renderItem,
    itemsRole,
    actions = false,
    hasFooter,
    isClosable = false,
    searchQuery,
    defaultSearchQuery,
    onSearchChange,
    onItemActivate,
    onTabSelect,

    ...rest
  } = props;

  // Mark hasFooter as intentionally accepted but unused for the React shell
  // (PanelShell derives footer visibility from `actions`). Documented for
  // API parity with the descriptor surface.
  void hasFooter;

  // -- Refs ----------------------------------------------------------------
  const hostRef = useRef<HTMLDivElement>(null);
  const paneRef = useRef<HTMLDivElement>(null);
  const pinBtnRef = useRef<HTMLButtonElement>(null);
  const shellRef = useRef<PanelShellHandle>(null);
  const prevFocusRef = useRef<HTMLElement | null>(null);
  const pinClickedRef = useRef(false);
  const splitterWarnedRef = useRef(false);

  // Focus trap activates only after slide-in completes (per descriptor
  // accessibility.focusManagement.focusTrap).
  const [trapActive, setTrapActive] = useState(false);

  // Forward host ref to consumer
  useImperativeHandle(ref, () => hostRef.current as HTMLDivElement, []);

  // -- Controlled state ----------------------------------------------------
  const [isPinnedState, setPinnedInternal] = useControllableState<boolean>(
    isPinnedProp,
    defaultPinned,
  );
  const [isOpenState, setOpenInternal] = useControllableState<boolean>(
    isOpenProp,
    defaultOpen,
  );

  // Imperative variant override (used when isPinnable is false). Pin-driven
  // variant takes precedence when isPinnable is true.
  const [variantOverride, setVariantOverride] = useState<ArvoSidePanelVariant | null>(null);

  const effectiveVariant: ArvoSidePanelVariant = isPinnable
    ? isPinnedState
      ? 'layout'
      : 'overlay'
    : (variantOverride ?? variantProp);

  // Layout variant is always considered "open"; overlay variant uses state.
  const open = effectiveVariant === 'layout' ? true : isOpenState;

  // -- Pin / open setters that fire callbacks ------------------------------
  const setPinned = useCallback(
    (next: boolean) => {
      if (next === isPinnedState) return;
      setPinnedInternal(next);
      onPinChange?.(next);
    },
    [isPinnedState, onPinChange, setPinnedInternal],
  );

  const setOpen = useCallback(
    (next: boolean) => {
      if (next === isOpenState) return;
      setOpenInternal(next);
      onOpenChange?.(next);
    },
    [isOpenState, onOpenChange, setOpenInternal],
  );

  // -- Open / close handlers (with cancellation) ---------------------------
  const handleOpen = useCallback(() => {
    if (effectiveVariant !== 'overlay') return;
    if (isOpenState) return;
    if (onOpen?.() === false) return;
    setOpen(true);
  }, [effectiveVariant, isOpenState, onOpen, setOpen]);

  const handleClose = useCallback(() => {
    if (effectiveVariant === 'overlay' && !isOpenState) return;
    if (onClose?.() === false) return;
    if (effectiveVariant === 'overlay') setOpen(false);
  }, [effectiveVariant, isOpenState, onClose, setOpen]);

  const handleToggle = useCallback(() => {
    if (effectiveVariant !== 'overlay') return;
    if (isOpenState) handleClose();
    else handleOpen();
  }, [effectiveVariant, isOpenState, handleOpen, handleClose]);

  // -- Pin click handler ---------------------------------------------------
  const handlePinClick = useCallback(() => {
    if (isDisabled) return;
    pinClickedRef.current = true;
    setPinned(!isPinnedState);
  }, [isDisabled, isPinnedState, setPinned]);

  // After a pin-driven flip, restore focus to the pin button.
  useEffect(() => {
    if (!pinClickedRef.current) return;
    pinClickedRef.current = false;
    pinBtnRef.current?.focus({ preventScroll: true });
  }, [isPinnedState]);

  // -- Overlay open/close lifecycle (animation + return-focus) -------------
  const wasOpenRef = useRef<boolean>(open);
  useEffect(() => {
    if (effectiveVariant !== 'overlay') {
      wasOpenRef.current = open;
      setTrapActive(false);
      return;
    }
    const prevOpen = wasOpenRef.current;
    wasOpenRef.current = open;
    if (open === prevOpen) return;

    const host = hostRef.current;
    if (!host) return;

    if (open) {
      // Capture previously-focused element so we can restore on close.
      if (typeof document !== 'undefined') {
        prevFocusRef.current = document.activeElement as HTMLElement | null;
      }
      void enter({ element: host, type: 'fade' }).then(() => {
        // Activate focus trap only AFTER slide-in completes.
        setTrapActive(true);
      });
    } else {
      // Deactivate trap synchronously before slide-out.
      setTrapActive(false);
      void exit({ element: host, type: 'fade' });
      const prev = prevFocusRef.current;
      prevFocusRef.current = null;
      if (prev && typeof prev.focus === 'function') {
        prev.focus({ preventScroll: true });
      }
    }
  }, [open, effectiveVariant]);

  // -- Focus trap (overlay variant + open + slide-in complete) -------------
  useFocusTrap(paneRef, {
    active: effectiveVariant === 'overlay' && open && trapActive && !isDisabled,
    initialFocus: 'first',
    escapeDeactivates: false,
    returnFocusOnDeactivate: false,
    allowOutsideClick: true,
  });

  // -- Escape handling (overlay variant only) ------------------------------
  useEffect(() => {
    if (effectiveVariant !== 'overlay' || !open || !closeOnEscape) return;
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        handleClose();
      }
    };
    document.addEventListener('keydown', onKeyDown, true);
    return () => document.removeEventListener('keydown', onKeyDown, true);
  }, [effectiveVariant, open, closeOnEscape, handleClose]);

  // -- Outside click (overlay variant + closeOnOutside) --------------------
  useEffect(() => {
    if (effectiveVariant !== 'overlay' || !open || !closeOnOutside) return;
    const onMouseDown = (e: MouseEvent) => {
      const target = e.target as Node | null;
      if (!target) return;
      const pane = paneRef.current;
      if (pane && pane.contains(target)) return;
      handleClose();
    };
    document.addEventListener('mousedown', onMouseDown, true);
    return () => document.removeEventListener('mousedown', onMouseDown, true);
  }, [effectiveVariant, open, closeOnOutside, handleClose]);

  // -- Splitter resolution -------------------------------------------------
  const splitterResolved = useMemo(() => {
    if (hasSplitter === 'auto') return effectiveVariant === 'layout';
    return hasSplitter === true;
  }, [hasSplitter, effectiveVariant]);

  useEffect(() => {
    if (
      splitterResolved &&
      !splitterWarnedRef.current &&
      typeof process !== 'undefined' &&
      process.env.NODE_ENV !== 'production'
    ) {
      splitterWarnedRef.current = true;
      console.warn(
        '[ArvoSidePanel] hasSplitter resolved truthy but ArvoSplitter is not yet available; rendering inert 4px placeholder. Resize behavior will activate when ArvoSplitter ships.',
      );
    }
  }, [splitterResolved]);

  // -- Imperative handle ---------------------------------------------------
  useImperativeHandle(
    instanceRef,
    () => ({
      pinned(value?: boolean): boolean | void {
        if (value === undefined) return isPinnedState;
        if (!isPinnable) return;
        setPinned(value);
      },
      setVariant(next: ArvoSidePanelVariant): void {
        if (isPinnable) {
          setPinned(next === 'layout');
          return;
        }
        setVariantOverride(next);
      },
      open: () => handleOpen(),
      close: () => handleClose(),
      toggle: () => handleToggle(),
      isOpen: () => open,
      setItems: (next) => shellRef.current?.setItems(next as ListItemBase[]),
      setStickyHeader: (config) => shellRef.current?.setStickyHeader(config),
      setHeaderActions: (next) => shellRef.current?.setHeaderActions(next),
      setActions: (next) => shellRef.current?.setActions(next),
      updateAction: (id, patch) => shellRef.current?.updateAction(id, patch),
      search(query?: string): string | void {
        if (query === undefined) return shellRef.current?.search() ?? '';
        shellRef.current?.search(query);
      },
      selectedTab(id?: string): string | null | void {
        if (id === undefined) return shellRef.current?.selectedTab() ?? null;
        shellRef.current?.selectedTab(id);
      },
      setTitle: (next) => shellRef.current?.setTitle(next),
      loading(state?: boolean): boolean | void {
        if (state === undefined) return isLoading;
        shellRef.current?.loading(state);
      },
      disabled(state?: boolean): boolean | void {
        if (state === undefined) return isDisabled;
        shellRef.current?.disabled(state);
      },
      focus: (target) => shellRef.current?.focus(target),
    }),
    [
      isPinnedState,
      isPinnable,
      setPinned,
      handleOpen,
      handleClose,
      handleToggle,
      open,
      isLoading,
      isDisabled,
    ],
  );

  // -- Class composition ---------------------------------------------------
  const splitterClass = splitterResolved
    ? side === 'right'
      ? 'arvo-sp--with-splitter-l'
      : 'arvo-sp--with-splitter-r'
    : null;

  const hostClasses = [
    'arvo-sp',
    `arvo-sp--${effectiveVariant}`,
    `arvo-sp--side-${side}`,
    isPinnable && 'arvo-sp--pinnable',
    isClosable && 'arvo-sp--closable',
    hasBackButton && 'arvo-sp--with-back',
    isPinnable && (isPinnedState ? 'is-pinned' : 'is-unpinned'),
    effectiveVariant === 'overlay' && open && 'open',
    isLoading && 'loading',
    isDisabled && 'is-disabled',
    splitterClass,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  // -- Inline CSS variables for width --------------------------------------
  const styleVars = useMemo<CSSProperties>(() => {
    const widthCss = toCssLength(width);
    const minWidthCss = toCssLength(minWidth);
    const maxWidthCss = toCssLength(maxWidth);
    const out: Record<string, string> = {};
    if (widthCss) out['--arvo-sp-width'] = widthCss;
    if (minWidthCss) out['--arvo-sp-min-width'] = minWidthCss;
    if (maxWidthCss) out['--arvo-sp-max-width'] = maxWidthCss;
    return out as CSSProperties;
  }, [width, minWidth, maxWidth]);

  // -- ARIA wiring (per descriptor: lives on __pane) -----------------------
  const role = effectiveVariant === 'overlay' ? 'dialog' : 'region';
  const ariaModalAttr = effectiveVariant === 'overlay' ? 'false' : undefined;
  const ariaHiddenAttr =
    effectiveVariant === 'overlay' && !open ? true : undefined;
  const computedAriaLabel = ariaLabel ?? title ?? undefined;

  // -- Splitter element ----------------------------------------------------
  const splitterEl = splitterResolved ? (
    <div className="arvo-sp__splitter" aria-hidden="true" />
  ) : null;

  const splitterFirst = side === 'right' ? splitterEl : null;
  const splitterLast = side === 'left' ? splitterEl : null;

  // -- Render --------------------------------------------------------------
  return (
    <div
      ref={hostRef}
      className={hostClasses}
      style={styleVars}
      {...rest}
    >
      {splitterFirst}
      <div
        ref={paneRef}
        className="arvo-sp__pane"
        role={role}
        aria-modal={ariaModalAttr}
        aria-hidden={ariaHiddenAttr}
        aria-busy={isLoading || undefined}
        aria-disabled={isDisabled || undefined}
        aria-label={computedAriaLabel}
      >
        <PanelShell<T>
          ref={shellRef as RefObject<PanelShellHandle>}
          parentBlock="arvo-sp"
          title={title}
          hasHeader={hasHeader}
          hasBackButton={hasBackButton}
          onBack={onBack}
          headerActions={headerActions}
          stickyHeader={stickyHeader}
          items={items}
          getItemId={getItemId}
          filterKeys={filterKeys}
          getItemSearchText={getItemSearchText}
          renderItem={renderItem}
          itemsRole={itemsRole}
          actions={actions}
          isClosable={isClosable}
          onClose={handleClose}
          isLoading={isLoading}
          isDisabled={isDisabled}
          isPinnableCount={isPinnable ? 1 : 0}
          isClosableCount={isClosable ? 1 : 0}
          searchQuery={searchQuery}
          defaultSearchQuery={defaultSearchQuery}
          onSearchChange={onSearchChange}
          onItemActivate={onItemActivate}
          onTabSelect={onTabSelect}
          pinSlot={
            isPinnable ? (
              <PinButton
                ref={pinBtnRef}
                isPinned={isPinnedState}
                isDisabled={isDisabled}
                onClick={handlePinClick}
              />
            ) : null
          }
        >
          {children}
        </PanelShell>
      </div>
      {splitterLast}
    </div>
  );
}

// Cast the forwardRef'd inner function to a generic component signature so
// consumers retain the `<T>` type parameter. Mirrors the pattern in
// PanelShell.tsx.
export const ArvoSidePanel = forwardRef(SidePanelInner) as <
  T extends ListItemBase = ListItemBase,
>(
  props: ArvoSidePanelProps<T> & { ref?: Ref<HTMLDivElement> },
) => ReactElement | null;

(ArvoSidePanel as unknown as { displayName: string }).displayName = 'ArvoSidePanel';

export default ArvoSidePanel;
